-- FIRM-001: the principal's firm settings. Empty on a fresh installation; one row once set up.
CREATE TABLE s_firm(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, line1 TEXT NOT NULL, line2 TEXT NOT NULL DEFAULT '', city TEXT NOT NULL, state TEXT NOT NULL, zip TEXT NOT NULL, timezone TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), default_rate_cents INTEGER NOT NULL, billing_increment_minutes INTEGER NOT NULL, payment_terms_days INTEGER NOT NULL, fiscal_year_start_month INTEGER NOT NULL CHECK(fiscal_year_start_month BETWEEN 1 AND 12), accounting_basis TEXT NOT NULL CHECK(accounting_basis IN('cash','accrual')), source TEXT NOT NULL CHECK(source IN('principal','import')), source_name TEXT NOT NULL DEFAULT '', source_digest TEXT NOT NULL DEFAULT '', revision TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE s_offices(id TEXT PRIMARY KEY, position INTEGER NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, line1 TEXT NOT NULL, line2 TEXT NOT NULL DEFAULT '', city TEXT NOT NULL, state TEXT NOT NULL, zip TEXT NOT NULL, timezone TEXT NOT NULL);
CREATE TABLE s_practice_areas(code TEXT PRIMARY KEY, position INTEGER NOT NULL, name TEXT NOT NULL);
